CREATE TABLE `merchantcategory` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category` varchar(100) DEFAULT NULL,
  `logoUrl` varchar(100) DEFAULT NULL,
  `subcategoryof` varchar(100) DEFAULT NULL,
  `isActive` tinyint(1) DEFAULT '0',
  `createdby` varchar(50) DEFAULT NULL,
  `modifiedby` varchar(50) DEFAULT NULL,
  `createdts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lastmodifiedts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `synctimestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `softdeleteflag` tinyint(1) NOT NULL DEFAULT '0',
  `labelText` varchar(45) DEFAULT NULL,
  `code` varchar(45) NOT NULL,
  `sequence` int DEFAULT NULL,
  `merchantType` varchar(45) DEFAULT NULL,
  `subcategoryLogourl` varchar(250) DEFAULT NULL,
  `paymentaggregator` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=278 DEFAULT CHARSET=utf8mb3

=================================================================================


CREATE TABLE `merchantdetails` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(100) NOT NULL,
  `categoryof` varchar(50) NOT NULL,
  `logoUrl` varchar(250) DEFAULT NULL,
  `paymentaggregator` varchar(100) DEFAULT 'connectIPS',
  `isActive` tinyint(1) DEFAULT '1',
  `labelText` varchar(100) NOT NULL,
  `fieldSetup` varchar(45) DEFAULT NULL,
  `disclimerMessage` varchar(45) DEFAULT NULL,
  `outageMessage` varchar(45) DEFAULT NULL,
  `subcategory` varchar(45) NOT NULL,
  `subcategoryCode` varchar(45) DEFAULT NULL,
  `categoryCode` varchar(45) DEFAULT NULL,
  `placeholderText` varchar(45) DEFAULT NULL,
  `maxTransactionLimit` varchar(125) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=630 DEFAULT CHARSET=utf8mb3

==================================================================================

CREATE TABLE `merchantfields` (
  `id` int NOT NULL AUTO_INCREMENT,
  `merchantCode` varchar(100) DEFAULT NULL,
  `fieldname` varchar(100) DEFAULT NULL,
  `fieldi18n` varchar(50) DEFAULT NULL,
  `fieldtype` varchar(100) DEFAULT NULL,
  `fieldindex` int NOT NULL DEFAULT '0',
  `fieldvalue` longtext,
  `isMandatory` tinyint(1) NOT NULL DEFAULT '0',
  `fieldname_np` varchar(45) DEFAULT NULL,
  `placeholder` varchar(45) DEFAULT NULL,
  `fieldcategory` varchar(45) DEFAULT NULL,
  `paramKey` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=378 DEFAULT CHARSET=utf8mb3

===================================================================================

CREATE TABLE `paymentaggregator` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) DEFAULT NULL,
  `isActive` tinyint(1) DEFAULT '0',
  `createdby` varchar(50) DEFAULT NULL,
  `modifiedby` varchar(50) DEFAULT NULL,
  `createdts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lastmodifiedts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `synctimestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `softdeleteflag` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb3


======================================================
CREATE TABLE `merchantpaymentcharges` (
  `id` int NOT NULL AUTO_INCREMENT,
  `merchantCode` varchar(45) DEFAULT NULL,
  `minAmount` varchar(120) DEFAULT NULL,
  `maxAmount` varchar(120) DEFAULT NULL,
  `fee` decimal(50,2) DEFAULT NULL,
  `chargesType` varchar(45) DEFAULT NULL,
  `maxTransactionAmount` decimal(50,2) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci

CREATE TABLE `mastermerchants` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(100) DEFAULT NULL,
  `isActive` tinyint(1) DEFAULT '0',
  `createdby` varchar(50) DEFAULT NULL,
  `modifiedby` varchar(50) DEFAULT NULL,
  `createdts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lastmodifiedts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `synctimestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `sequence` int DEFAULT NULL,
  `softdeleteflag` tinyint(1) NOT NULL DEFAULT '0',
  `logoUrl` varchar(100) DEFAULT NULL,
  `name` varchar(45) DEFAULT NULL,
  `code` varchar(45) NOT NULL,
  `subcategoryof` varchar(100) DEFAULT NULL,
  `categoryCode` varchar(45) DEFAULT NULL,
  `subcategoryLogourl` varchar(250) DEFAULT NULL,
  `categoryLogourl` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb3


